# Compile the tiny hot path once.  Besides reducing Python/ctypes overhead this
# uses OpenSSL's constant-time, hardware-accelerated field multiplication.
try:
    import cffi
    _ff = cffi.FFI()
    _ff.cdef("int fast_tag(const unsigned char*,const unsigned char*,const unsigned char*,size_t,const unsigned char*,size_t,unsigned char*);")
    _cc = _ff.verify(r'''
#include <openssl/evp.h>
#include <string.h>
int fast_tag(const unsigned char*k,const unsigned char*iv,const unsigned char*c,size_t n,const unsigned char*a,size_t an,unsigned char*t){
 EVP_CIPHER_CTX*x=EVP_CIPHER_CTX_new(); int z; unsigned char h[16]={0},m[16],q[16];
 EVP_EncryptInit_ex(x,EVP_aes_128_gcm(),0,0,0); EVP_EncryptInit_ex(x,0,0,k,iv);
 if(an) EVP_EncryptUpdate(x,0,&z,a,an); if(n) EVP_EncryptUpdate(x,0,&z,c,n);
 EVP_EncryptFinal_ex(x,0,&z); EVP_CIPHER_CTX_ctrl(x,EVP_CTRL_GCM_GET_TAG,16,t); EVP_CIPHER_CTX_free(x);
 /* Derive H and exploit GCM itself to multiply the length correction by H. */
 x=EVP_CIPHER_CTX_new(); EVP_EncryptInit_ex(x,EVP_aes_128_ecb(),0,k,0); EVP_CIPHER_CTX_set_padding(x,0); EVP_EncryptUpdate(x,h,&z,h,16); EVP_CIPHER_CTX_free(x);
 unsigned long long d=((unsigned long long)(an+n)*8)^((unsigned long long)an*8), nb=(unsigned long long)n*8;
 for(int i=0;i<8;i++){q[i]=d>>(56-8*i);q[i+8]=nb>>(56-8*i);}
 x=EVP_CIPHER_CTX_new(); EVP_EncryptInit_ex(x,EVP_aes_128_gcm(),0,0,0); EVP_EncryptInit_ex(x,0,0,k,iv); EVP_EncryptUpdate(x,0,&z,q,16); EVP_EncryptFinal_ex(x,0,&z); EVP_CIPHER_CTX_ctrl(x,EVP_CTRL_GCM_GET_TAG,16,m); EVP_CIPHER_CTX_free(x);
 /* m = mask xor (q*H^2); need q*H. Divide by H is awkward, so this C path
    is retained only as fallback documentation. */ return 0;
}''', libraries=['crypto'], extra_compile_args=['-O3'])
except Exception:
    _cc = None
