"""Parallel gzip compressor."""
import concurrent.futures
import struct
import zlib


def _compress_piece(item):
    data, dictionary = item
    if dictionary:
        obj = zlib.compressobj(9, zlib.DEFLATED, -15, 8,
                               zlib.Z_DEFAULT_STRATEGY, zdict=dictionary)
    else:
        obj = zlib.compressobj(9, zlib.DEFLATED, -15)
    # SYNC_FLUSH makes each independently generated stream byte-aligned, while
    # leaving it possible to append another deflate block.
    return obj.compress(data) + obj.flush(zlib.Z_SYNC_FLUSH)


class Solver:
    def __init__(self):
        self._workers = 12
        self._pool = concurrent.futures.ThreadPoolExecutor(max_workers=self._workers)

    def solve(self, problem, **kwargs):
        plaintext = problem["plaintext"]
        if not plaintext:
            # The generic path also works, but this is both simpler and faster.
            import gzip
            return {"compressed_data": gzip.compress(plaintext, 9, mtime=0)}

        n = self._workers
        size = (len(plaintext) + n - 1) // n
        jobs = []
        for start in range(0, len(plaintext), size):
            # Supplying the preceding deflate window preserves matches across
            # parallel chunk boundaries without putting those bytes in output.
            dictionary = plaintext[max(0, start - 32768):start]
            jobs.append((plaintext[start:start + size], dictionary))
        raw = b"".join(self._pool.map(_compress_piece, jobs)) + b"\x03\x00"
        header = b"\x1f\x8b\x08\x00\x00\x00\x00\x00\x00\x03"
        trailer = struct.pack("<II", zlib.crc32(plaintext), len(plaintext) & 0xffffffff)
        return {"compressed_data": header + raw + trailer}

