"""Fast Cholesky factorization using SciPy's direct LAPACK binding."""
from scipy.linalg.lapack import dpotrf

class Solver:
    def solve(self, problem, **kwargs):
        # Transpose is a zero-copy Fortran-order view (the input is symmetric).
        # Factor in place and clear LAPACK's unused triangle with contiguous
        # column slices, avoiding dpotrf(clean=True)'s relatively costly pass.
        L, info = dpotrf(problem["matrix"].T, lower=True,
