import numpy as np
from scipy.linalg import lapack
def _s(x,y):return 0
class Solver:
 def solve(self,A,**kw):
  T,_,wr,wi,Q,_,_=lapack.dgees(_s,np.asarray(A),compute_v=1,sort_t=0,lwork=450,overwrite_a=1)
  n=len(wr); lam=wr+1j*wi; Z=np.zeros((n,n),complex)
  # seed each real eigenvector / conjugate pair
  for k in range(n):
   if wi[k]>0: Z[k+1,k]=1; Z[k,k]=-T[k,k+1]/(T[k,k]-lam[k])
   elif wi[k]<0: Z[k-1,k]=1; Z[k,k]=-(T[k-1,k-1]-lam[k])/T[k-1,k]
   else: Z[k,k]=1
  i=n-1
  while i>=0:
   if i>0 and T[i,i-1]!=0:
    cols=np.arange(i+1,n)
    if len(cols):
     R=-T[i-1:i+1,i+1:]@Z[i+1:,i+1:]
     a=T[i-1,i-1]-lam[cols];d=T[i,i]-lam[cols];b=T[i-1,i];c=T[i,i-1];det=a*d-b*c
     Z[i-1,cols]=(R[0]*d-b*R[1])/det;Z[i,cols]=(a*R[1]-c*R[0])/det
    i-=2
   else:
    cols=np.arange(i+1,n)
    if len(cols): Z[i,cols]=-(T[i,i+1:]@Z[i+1:,i+1:])/(T[i,i]-lam[cols])
    i-=1
  V=Q@Z;o=np.lexsort((-wi,-wr));V=V[:,o];V/=np.linalg.norm(V,axis=0)
  return V.T.tolist()

