from scipy.linalg import lapack

def _sel(x,y): return 0
class Solver:
 def solve(self, problem, **kwargs):
  A=np.array(problem,dtype=np.float32,order='F')
  T,sd,wr,wi,Q,work,info=lapack.sgees(_sel,A,compute_v=1,sort_t=0,lwork=450,overwrite_a=1)
  # Eigenvectors of an upper quasi-triangular matrix by fast back substitution.
  n=len(wr); V=np.zeros((n,n),complex); vals=wr.astype(float)+1j*wi.astype(float)
  for k in range(n):
   lam=vals[k]; x=np.zeros(n,complex)
   if wi[k]>0:
    x[k+1]=1; x[k]=-(T[k,k+1])/(T[k,k]-lam); start=k-1
   elif wi[k]<0:
    x[k-1]=1; x[k]=-(T[k-1,k-1]-lam)/T[k-1,k]; start=k-2
   else: x[k]=1; start=k-1
   for i in range(start,-1,-1):
    # coupled row when this is lower member of a real 2x2 block
    if i>0 and T[i,i-1]!=0:
     r1=-np.dot(T[i-1,i+1:],x[i+1:]); r2=-np.dot(T[i,i+1:],x[i+1:])
     a=T[i-1,i-1]-lam;b=T[i-1,i];c=T[i,i-1];d=T[i,i]-lam
