    elif i+1<=start and T[i+1,i]!=0: continue
    else: x[i]=-np.dot(T[i,i+1:],x[i+1:])/(T[i,i]-lam)
   V[:,k]=Q@x
  order=np.lexsort((-vals.imag,-vals.real)); V=V[:,order];V/=np.linalg.norm(V,axis=0)
