import numpy as np
import scipy.linalg

class Solver:
    def solve(self, problem, **kwargs):
        A = problem["matrix"]
        n = A.shape[0]
        X = np.eye(n, dtype=np.complex128) * np.sqrt(.25*np.linalg.norm(A, np.inf))
        best, least = X, np.inf
        # Newton iteration from a scalar matrix converges to the principal root.
        for _ in range(18):
            X = .5*(X + scipy.linalg.solve(X, A, check_finite=False))
            residual = np.max(np.abs(X @ X - A))
            if residual < least:
                least, best = residual, X.copy()
            if residual < 1e-9:
                break
        R = A-best@best
        # Rare difficult cases only: Newton/Sylvester refinement of the residual.
        if np.max(np.abs(R)) > 5e-8:
            best += scipy.linalg.solve_sylvester(best, best, R)
            R = A-best@best
            if np.max(np.abs(R)) > 1e-8:
                best += scipy.linalg.solve_sylvester(best, best, R)
        return {"sqrtm": {"X": best.tolist()}}

