import numpy as np
from numba import njit

@njit(cache=True)
def _auction(C):
    n=C.shape[0]
    price=np.zeros(n); own=np.full(n,-1,np.int32); ass=np.full(n,-1,np.int32)
    stack=np.empty(n,np.int32)
    eps=.1
    while eps>1e-8:
        own[:]=-1; ass[:]=-1
        for i in range(n): stack[i]=i
        top=n
        while top:
            top-=1; i=stack[top]
            best=-1e300; second=-1e300; bj=-1
            for j in range(n):
                x=-C[i,j]-price[j]
                if x>best:
                    second=best; best=x; bj=j
                elif x>second: second=x
            price[bj] += best-second+eps
            old=own[bj]; own[bj]=i; ass[i]=bj
            if old>=0:
                stack[top]=old; top+=1
        eps *= .1
    return ass

class Solver:
    def solve(self, problem, **kwargs):
        a=np.asarray(problem['source_weights']); b=np.asarray(problem['target_weights']); M=np.asarray(problem['cost_matrix'])
        if len(a)==len(b) and np.all(a==a[0]) and np.all(b==b[0]) and a[0]==b[0]:
            c=_auction(M)
            G=np.zeros(M.shape); G[np.arange(len(a)),c]=a[0]
            return {'transport_plan':G}
        import ot
        return {'transport_plan':ot.lp.emd(a,b,np.ascontiguousarray(M,dtype=np.float64),check_marginals=False)}

